pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Response time is less than 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});
const response = pm.response.json();

pm.test("Response has expected structure", function () {
    pm.expect(response).to.have.property("result");
    pm.expect(response).to.have.property("base_code");
    pm.expect(response).to.have.property("rates");
    pm.expect(response).to.have.property("provider");
    pm.expect(response).to.have.property("documentation");
});

const targetCurrency = pm.iterationData.get("target_currency");

pm.test("Target currency exists", function () {
    pm.expect(response.rates).to.have.property(targetCurrency);
});

pm.test("Target currency rate is sensible", function () {
    const rate = response.rates[targetCurrency];

    pm.expect(rate).to.be.a("number");
    pm.expect(rate).to.be.above(0);
});
